args<-commandArgs(TRUE); P<-normalizePath(args[1]); W<-file.path(P,'work/2026-10-28-destiny-guo'); C<-file.path(P,'biofigure/benchmark/library/single-cell/destiny-guo-dpt-2026')
.libPaths(c(file.path(W,'Rlib'),.libPaths()))
suppressPackageStartupMessages({library(destiny);library(Biobase);library(ggplot2);library(grid);library(gridExtra);library(ggplotify);library(jsonlite)})
stopifnot(as.character(packageVersion('destiny'))=='3.26.0')
load(file.path(C,'data/raw/guo.rda'))
set.seed(1); dm<-DiffusionMap(guo); dpt<-DPT(dm)
set.seed(4); random_tips<-sample(ncol(guo),3L);dpt_random<-DPT(dm,tips=random_tips)
divided<-branch_divide(dpt,3)
grad<-colorRampPalette(c('#356A86','#DB93A1'),space='Lab')
marker_grad<-colorRampPalette(c('#F3E6DE','#B3687E'),space='Lab')
branch_pal<-c('#356A86','#B3687E','#90B6C7');divided_pal<-c('#356A86','#B3687E','#718CA5','#B1BDCF','#D5A0AD')
paths<-c('#356A86','#B3687E');tipcol<-'#30343B'
base_theme<-theme_minimal(base_family='Arial',base_size=7)+theme(panel.grid.minor=element_blank(),panel.grid.major=element_line(colour='#E8E9EB',linewidth=.15),axis.title=element_text(size=7),axis.text=element_blank(),legend.title=element_text(size=7),legend.text=element_text(size=6.5),legend.key.height=unit(2.4,'mm'),legend.key.width=unit(2.4,'mm'),legend.spacing.y=unit(1,'mm'),legend.box.spacing=unit(2,'mm'),legend.margin=margin(0,0,0,0),plot.margin=margin(3,3,3,3),plot.tag=element_text(family='Arial',face='bold',size=9))
style<-function(p,tag){p+base_theme+labs(tag=tag)+theme(plot.tag.position=c(0,.97))}
p1<-style(plot(dpt,pal=grad,col_tip=tipcol,legend_main='DPT1'),'a')
p2<-style(plot(dpt_random,pal=grad,col_tip=tipcol,legend_main='DPT1'),'b')
p3<-style(plot(dpt,col_by='DPT3',pal=grad,col_tip=tipcol,legend_main='DPT3'),'c')
p4<-style(plot(dpt,col_by='Gata4',pal=marker_grad,col_tip=tipcol,legend_main='Gata4'),'d')
p5<-style(plot(dpt,root=2,paths_to=c(1,3),col_by='branch',pal=branch_pal,col_path=paths,col_tip=tipcol,col_na='#C6CBCF',legend_main='Branch'),'e')
# Native scatterplot3d projection and DPT branch subdivision; no hand-drawn coordinates.
p6<-ggplotify::as.grob(function(){
 par(family='Arial',cex=.65,cex.lab=.85,mar=c(2.5,2.5,.8,.5),mgp=c(1.7,.6,0),las=1)
 plot(dpt,col_by='branch',divide=3,dcs=c(-1,-3,2),pch=20,pal=divided_pal,col_tip=tipcol,col_na='#C6CBCF',cex.symbols=.55,draw_legend=FALSE,angle=40)
})
legend6<-grobTree(textGrob('Branch',x=.15,y=.85,just='left',gp=gpar(fontfamily='Arial',fontsize=7)),pointsGrob(x=rep(.18,6),y=seq(.73,.18,length.out=6),pch=16,size=unit(1.1,'mm'),gp=gpar(col=c(divided_pal,'#C6CBCF'))),textGrob(c('1','2','46','47','48','Unassigned'),x=.34,y=seq(.73,.18,length.out=6),just='left',gp=gpar(fontfamily='Arial',fontsize=6.5)))
p6<-arrangeGrob(p6,legend6,ncol=2,widths=c(.77,.23))
p6<-grobTree(p6,textGrob('f',x=unit(1,'mm'),y=unit(1,'npc')-unit(2,'mm'),just=c('left','top'),gp=gpar(fontfamily='Arial',fontsize=9,fontface='bold')),textGrob('DC1',x=unit(.385,'npc'),y=unit(1.8,'mm'),gp=gpar(fontfamily='Arial',fontsize=7)))
g<-arrangeGrob(p1,p2,p3,p4,p5,p6,ncol=2,widths=c(1,1),heights=c(1,1,1))
labels<-character();sizes<-numeric()
fix<-function(x){if(inherits(x,'text')){x$gp$fontfamily<-'Arial';if(!is.null(x$gp$fontsize)){x$gp$fontsize<-pmax(6.5,x$gp$fontsize);sizes<<-c(sizes,x$gp$fontsize)};if(!is.expression(x$label))labels<<-c(labels,as.character(x$label))};if(length(x$grobs))x$grobs<-lapply(x$grobs,fix);if(length(x$children))x$children<-do.call(gList,lapply(x$children,fix));x}
g<-fix(g);p<-ggplotify::as.ggplot(g)+theme_void(base_family='Arial',base_size=7)+theme(plot.margin=margin(0,0,0,0),text=element_text(family='Arial',size=7))
saveRDS(p,file.path(W,'render-object.rds'));saveRDS(g,file.path(W,'composed-grob.rds'));saveRDS(list(dm=dm,dpt=dpt,dpt_random=dpt_random,guo=guo),file.path(W,'computations.rds'))
ragg::agg_png(file.path(W,'exploratory.png'),width=183,height=165,units='mm',res=220,background='white');print(p);dev.off()
d<-data.frame(cell_id=guo$Cell,stage=guo$num_cells,eigenvectors(dm)[,1:3],DPT1=dpt[['DPT1']],DPT3=dpt[['DPT3']],random_DPT1=dpt_random[['DPT1']],Gata4=exprs(guo)['Gata4',],branch=dpt@branch[,1],divided_branch=divided@branch[,1],check.names=FALSE)
write.csv(d,file.path(C,'results/plot_data/destiny-guo-dpt-coordinates.csv'),row.names=FALSE)
write.csv(data.frame(cell_id=guo$Cell,t(exprs(guo)),check.names=FALSE),file.path(C,'results/plot_data/guo-normalized-ct.csv'),row.names=FALSE)
write.csv(data.frame(component=seq_along(eigenvalues(dm)),eigenvalue=eigenvalues(dm)),file.path(C,'results/plot_data/diffusion-eigenvalues.csv'),row.names=FALSE)
branch_counts<-table(divided@branch[,1],useNA='always');names(branch_counts)[is.na(names(branch_counts))]<-'Unassigned'
jsonlite::write_json(list(status='SOURCE_COMPUTATION_COMPLETE_PENDING_VISUAL_REVIEW',labels=unique(labels[nzchar(labels)]),font_sizes=sort(unique(sizes)),n_cells=ncol(guo),n_genes=nrow(guo),celltype_counts=as.list(table(guo$num_cells)),auto_tips=tips(dpt),random_tips=random_tips,divided_branches=as.list(branch_counts),seed_diffusion=1,seed_random_tips=4,package_version=as.character(packageVersion('destiny'))),file.path(W,'data-qc.json'),auto_unbox=TRUE,pretty=TRUE)
writeLines(capture.output(sessionInfo()),file.path(C,'data/metadata/sessionInfo.txt'))
